using System; using System.Data; using System.Data.SqlClient; using FindIt.Models; namespace FindIt.DAL { public class UserRepository { public User ByEmail(string email){using(var c=DatabaseHelper.GetConnection()) using(var cmd=new SqlCommand("SELECT UserId,FullName,Email,PasswordHash,Role,Phone,CreatedAt,IsActive FROM Users WHERE Email=@e",c)){cmd.Parameters.Add("@e",SqlDbType.NVarChar,200).Value=email.Trim(); c.Open(); using(var r=cmd.ExecuteReader()){return r.Read()?Map(r):null;}}} public bool Create(RegisterViewModel v,string hash){using(var c=DatabaseHelper.GetConnection()) using(var cmd=new SqlCommand("INSERT INTO Users(FullName,Email,PasswordHash,Role,Phone) VALUES(@n,@e,@h,'Student',@p)",c)){cmd.Parameters.Add("@n",SqlDbType.NVarChar,100).Value=v.FullName.Trim();cmd.Parameters.Add("@e",SqlDbType.NVarChar,200).Value=v.Email.Trim().ToLowerInvariant();cmd.Parameters.Add("@h",SqlDbType.NVarChar,300).Value=hash;cmd.Parameters.Add("@p",SqlDbType.NVarChar,20).Value=(object)v.Phone??DBNull.Value;c.Open();try{return cmd.ExecuteNonQuery()==1;}catch(SqlException ex){if(ex.Number==2601||ex.Number==2627)return false;throw;}}} public User Get(int id){using(var c=DatabaseHelper.GetConnection())using(var cmd=new SqlCommand("SELECT UserId,FullName,Email,PasswordHash,Role,Phone,CreatedAt,IsActive FROM Users WHERE UserId=@id",c)){cmd.Parameters.AddWithValue("@id",id);c.Open();using(var r=cmd.ExecuteReader())return r.Read()?Map(r):null;}} public DataTable All(){using(var c=DatabaseHelper.GetConnection())using(var da=new SqlDataAdapter("SELECT UserId,FullName,Email,Role,Phone,CreatedAt,IsActive FROM Users ORDER BY CreatedAt DESC",c)){var t=new DataTable();da.Fill(t);return t;}} public void SetActive(int id,bool active){using(var c=DatabaseHelper.GetConnection())using(var cmd=new SqlCommand("UPDATE Users SET IsActive=@a WHERE UserId=@id AND Role='Student'",c)){cmd.Parameters.AddWithValue("@a",active);cmd.Parameters.AddWithValue("@id",id);c.Open();cmd.ExecuteNonQuery();}} private User Map(SqlDataReader r){return new User{UserId=r.GetInt32(0),FullName=r.GetString(1),Email=r.GetString(2),PasswordHash=r.GetString(3),Role=r.GetString(4),Phone=r.IsDBNull(5)?null:r.GetString(5),CreatedAt=r.GetDateTime(6),IsActive=r.GetBoolean(7)};} } }